#endif
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m;
    cin>>m;
    vector<vector<long long>> cnt(26, vector<long long>(26,0));
    string s;
    for(int i=0;i<m;++i){
        cin>>s;
        int a = s.front()-'A';
        int b = s.back()-'A';
        cnt[a][b] ++;
    }
    __int128 ans = 0;
    for(int x=0;x<26;++x) for(int y=0;y<26;++y)
    for(int u=0;u<26;++u) for(int v=0;v<26;++v){

        pair<int,int> t1 = {x,y}, t2 = {u,v}, t3 = {x,u}, t4 = {y,v};

        pair<int,int> types[4] = {t1,t2,t3,t4};

        array<pair<pair<int,int>,int>,4> temp;
        int tcnt = 0;
        bool found;
        for(int i=0;i<4;++i){
            found = false;
            for(int j=0;j<tcnt;++j){
                if(temp[j].first == types[i]) { temp[j].second++; found = true; break; }
            }
            if(!found){
                temp[tcnt++] = {types[i],1};
            }
        }
        bool ok = true;
        __int128 ways = 1;
        for(int j=0;j<tcnt && ok;++j){
            int a = temp[j].first.first;
            int b = temp[j].first.second;
            int need = temp[j].second;
            long long have = cnt[a][b];
            if(have < need){ ok = false; break; }

            __int128 mult = 1;
            for(int k=0;k<need;++k) mult *= (__int128)(have - k);
            ways *= mult;
        }
        if(ok) ans += ways;
    }

    if(ans==0){ cout << 0 << '\n'; return 0; }
    __int128 tmp = ans;
    bool neg = false;
    if(tmp < 0){ neg = true; tmp = -tmp; }
    string out;
    while(tmp > 0){
        int digit = (int)(tmp % 10);
        out.push_back('0' + digit);
        tmp /= 10;
    }
    if(neg) out.push_back('-');
    reverse(out.begin(), out.end());
    cout << out << '\n';
}